73	                        "CubeFormatAttr":$cubeFormatAAttr, "Type":$typeA,
74	                        "bool":$isTransA, "LayoutModeAttr":$layoutModeAAttr,
75	                        "TPositionAttr":$srcBPositionAttr,
76	                        "CubeFormatAttr":$cubeFormatBAttr, "Type":$typeB,
