79	                        "CubeFormatAttr":$cubeFormatCAttr, "Type":$typeC,
80	                        "bool":$isTransC, "LayoutModeAttr":$layoutModeCAttr,
81	                        "TPositionAttr":$srcBiasPositionAttr,
