91	  let builders = [
92	    TypeBuilder<(ins "TPosition":$srcAPosition, "CubeFormat":$cubeFormatA,
93	                 "Type":$typeA, "bool":$isTransA, "LayoutMode":$layoutModeA, "TPosition":$srcBPosition, "CubeFormat":$cubeFormatB,
94	                 "Type":$typeB, "bool":$isTransB, "LayoutMode":$layoutModeB, "TPosition":$srcCPosition, "CubeFormat":$cubeFormatC,
95	                 "Type":$typeC, "bool":$isTransC, "LayoutMode":$layoutModeC, "TPosition":$srcBiasPosition,
96	                 "CubeFormat":$cubeFormatBias, "Type":$typeBias, "MatmulConfigAttr":$matmulConfig), [{
97	      auto srcA = TPositionAttr::get($_ctxt, srcAPosition);
98	      auto formatA = CubeFormatAttr::get($_ctxt, cubeFormatA);
99	      auto layoutA = LayoutModeAttr::get($_ctxt, layoutModeA);
100	      auto srcB = TPositionAttr::get($_ctxt, srcBPosition);
101	      auto formatB = CubeFormatAttr::get($_ctxt, cubeFormatB);
102	      auto layoutB = LayoutModeAttr::get($_ctxt, layoutModeB);
103	      auto srcC = TPositionAttr::get($_ctxt, srcCPosition);
104	      auto formatC = CubeFormatAttr::get($_ctxt, cubeFormatC);
105	      auto layoutC = LayoutModeAttr::get($_ctxt, layoutModeC);
106	      auto srcBias = TPositionAttr::get($_ctxt, srcBiasPosition);
107	      auto formatBias = CubeFormatAttr::get($_ctxt, cubeFormatBias);
108	      return $_get($_ctxt, srcA, formatA, typeA, isTransA, layoutA,
109	                    srcB, formatB, typeB, isTransB, layoutB,
110	                    srcC, formatC, typeC, isTransC, layoutC,
111	                    srcBias, formatBias, typeBias, matmulConfig);
112	    }]>,
113	  ];
114	  let extraClassDeclaration = [{
115	    TPosition getSrcAPosition() { return getSrcAPositionAttr().getValue(); }
116	    TPosition getSrcBPosition() { return getSrcBPositionAttr().getValue(); }
117	    TPosition getSrcCPosition() { return getSrcCPositionAttr().getValue(); }
118	    TPosition getSrcBiasPosition() { return getSrcBiasPositionAttr().getValue(); }
119	    CubeFormat getCubeFormatA() { return getCubeFormatAAttr().getValue(); }
120	    CubeFormat getCubeFormatB() { return getCubeFormatBAttr().getValue(); }
121	    CubeFormat getCubeFormatC() { return getCubeFormatCAttr().getValue(); }
122	    LayoutMode getLayoutModeA() { return getLayoutModeAAttr().getValue(); }
123	    LayoutMode getLayoutModeB() { return getLayoutModeBAttr().getValue(); }
124	    LayoutMode getLayoutModeC() { return getLayoutModeCAttr().getValue(); }
